	\title{Movable-Element STARS-Assisted NOMA Communications}





	\author{Jingjing Zhao,~\IEEEmembership{Senior Member,~IEEE}, Yiheng Zhang, Kaiquan Cai, Xidong Mu, and Yuanwei Liu,~\IEEEmembership{Fellow,~IEEE}

		\thanks{J. Zhao, Y. Zhang, K. Cai are with the School of Electronics and Information Engineering, Beihang University, 100191, Beijing, China, and also with the State Key Laboratory of CNS/ATM, 100191, Beijing, China. (e-mail:\{jingjingzhao, zhangyiheng, ckq\}@buaa.edu.cn). 

